redirect_summary.code_js:
const requests = network.requests();
const redirects = requests.filter(r => r.responseStatus >= 300 && r.responseStatus < 400);
return redirects.length === 0 ? 'None' : redirects.map(r => `${r.url} (${r.responseStatus})`).join('; ');
